import React, { useEffect, useState } from "react";
import axios from "axios";

function QuizStudent() {
  const studentId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState("");
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [score, setScore] = useState(null);

  // 🔥 Load courses
  useEffect(() => {
    axios.get("http://127.0.0.1:8000/courses")
      .then(res => setCourses(res.data.courses || []));
  }, []);

  // 🔥 Load quiz by course
  useEffect(() => {
    if (!selectedCourse) return;

    axios
      .get(`http://127.0.0.1:8000/course-quiz/${selectedCourse}`)
      .then(res => {
        setQuestions(res.data.questions || []);
      })
      .catch(err => console.error(err));
  }, [selectedCourse]);

  const handleChange = (qId, option) => {
    setAnswers({
      ...answers,
      [qId]: option
    });
  };

  const submitQuiz = async () => {
    try {
      const res = await axios.post(
        "http://127.0.0.1:8000/submit-quiz",
        {
          quiz_id: 1, // backend se dynamic kar sakte ho next step me
          student_id: parseInt(studentId),
          answers: answers
        }
      );

      setScore(res.data.score);

      // 🔥 Planner auto refresh
      window.dispatchEvent(new Event("plannerUpdated"));

    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div>
      <h2 style={{ color: "#6a1b9a" }}>Quiz Section 🧠</h2>

      {/* Course Select */}
      <select
        onChange={(e) => setSelectedCourse(e.target.value)}
        style={input}
      >
        <option value="">Select Subject</option>
        {courses.map(c => (
          <option key={c.id} value={c.id}>
            {c.title}
          </option>
        ))}
      </select>

      {questions.map((q, index) => (
        <div key={q.id} style={card}>
          <h4>
            Q{index + 1}. {q.question}
          </h4>

          {[q.option1, q.option2, q.option3, q.option4].map((opt, i) => (
            <label key={i} style={option}>
              <input
                type="radio"
                name={q.id}
                value={opt}
                onChange={() => handleChange(q.id, opt)}
              />
              {opt}
            </label>
          ))}
        </div>
      ))}

      {questions.length > 0 && (
        <button onClick={submitQuiz} style={btn}>
          Submit Quiz
        </button>
      )}

      {score !== null && (
        <h3 style={{ color: "green" }}>
          Your Score: {score} / {questions.length}
        </h3>
      )}
    </div>
  );
}

/* Styles */
const input = {
  padding: "10px",
  marginBottom: "15px",
  borderRadius: "8px",
  width: "100%"
};

const card = {
  background: "#fff",
  padding: "15px",
  marginBottom: "10px",
  borderRadius: "10px"
};

const option = {
  display: "block",
  marginBottom: "5px"
};

const btn = {
  background: "#7b1fa2",
  color: "#fff",
  padding: "10px",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer"
};

export default QuizStudent;
